import fs from "node:fs";
import path from "node:path";
import { REDIRECTS } from "./redirects.mjs";

const outDir = path.resolve("deploy");
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}

const lines = [
  "# AUTO-GENERATED by scripts/generate-nginx.mjs — do not edit.",
  "# 308 Permanent Redirects for legacy routes",
  ...REDIRECTS.map(([src, dst]) => `location = ${src} { return 308 ${dst}; }`),
  "",
];

fs.writeFileSync(path.join(outDir, "nginx-redirects.conf"), lines.join("\n"));
console.log(`generate-nginx: wrote ${REDIRECTS.length} redirects to deploy/nginx-redirects.conf`);
